import { ActionMetrics, SimResult, SimResultFilter } from '../../proto_utils/sim_result.js';
import { bucket } from '../../utils.js';
import { formatDeltaTextElem } from '../../utils.js'; 

import { ColumnSortType, MetricsTable } from './metrics_table.js';
import { ResultComponent, ResultComponentConfig, SimResultData } from './result_component.js';

export class MeleeMetricsTable extends MetricsTable<ActionMetrics> {
	constructor(config: ResultComponentConfig) {
		config.rootCssClass = 'melee-metrics-root';
		
		// Closure to hold the data
		let lastSimResult: SimResultData | null = null;
		config.resultsEmitter.on((eventID, resultData) => {
			lastSimResult = resultData;
		});

		const renderDiffCell = (metric: ActionMetrics, cellElem: HTMLElement, getValue: (m: ActionMetrics) => number, precision: number, isPercent: boolean = false, lowerIsBetter: boolean = false) => {
			const val = getValue(metric);
			
			// Clear the cell first
			cellElem.innerHTML = '';

			const baseSpan = document.createElement('span');
			baseSpan.textContent = val.toFixed(precision) + (isPercent ? '%' : '');

			if (lastSimResult && lastSimResult.referenceResult) {
				const refPlayers = lastSimResult.referenceResult.getPlayers(lastSimResult.filter);
				if (refPlayers.length === 1) {
					const refPlayer = refPlayers[0];
					
					let refActions: ActionMetrics[] = [];
					if (metric.unit?.isPet) {
						const refPet = refPlayer.pets.find(p => p.name === metric.unit?.name);
						if (refPet) {
							refActions = refPet.getMeleeActions().map(a => a.forTarget(lastSimResult!.filter));
						}
					} else {
						refActions = refPlayer.getMeleeActions().map(a => a.forTarget(lastSimResult!.filter));
					}

					const refAction = refActions.find(a => a.actionId.equals(metric.actionId));
					if (refAction) {
						const refVal = getValue(refAction);
						if (val !== refVal) {
							const deltaSpan = document.createElement('span');
							formatDeltaTextElem(deltaSpan, refVal, val, precision, lowerIsBetter, false, false);
							if (isPercent) {
								deltaSpan.textContent += '%';
							}
							
							deltaSpan.textContent = `(${deltaSpan.textContent})`;
							
							// CHANGED: Margin on the right, appended first
							deltaSpan.style.marginRight = '6px';
							deltaSpan.style.fontSize = '0.65em';
							deltaSpan.style.opacity = '0.85'; 
							deltaSpan.style.whiteSpace = 'nowrap'; 
							
							cellElem.appendChild(deltaSpan);
						}
					}
				}
			}
			
			// Append the base value last so it stays anchored to the right side of the cell
			cellElem.appendChild(baseSpan);
		};
		
		super(config, [
			MetricsTable.nameCellConfig((metric: ActionMetrics) => {
				return {
					name: metric.name,
					actionId: metric.actionId,
				};
			}),
			{
				name: 'Damage',
				tooltip: 'Damage',
				getValue: (metric: ActionMetrics) => metric.damage,
				//getDisplayString: (metric: ActionMetrics) => metric.damage.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.damage, 1),
			},
			{
				name: 'DPS',
				tooltip: 'Damage / Encounter Duration',
				sort: ColumnSortType.Descending,
				getValue: (metric: ActionMetrics) => metric.dps,
				//getDisplayString: (metric: ActionMetrics) => metric.dps.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.dps, 1),
			},
			{
				name: 'Avg Cast',
				tooltip: 'Damage / Casts',
				getValue: (metric: ActionMetrics) => metric.avgCast,
				//getDisplayString: (metric: ActionMetrics) => metric.avgCast.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.avgCast, 1),
				
			},
			{
				name: 'Avg Hit',
				tooltip: 'Damage / (Hits + Crits + Glances + Blocks)',
				getValue: (metric: ActionMetrics) => metric.avgHit,
				//getDisplayString: (metric: ActionMetrics) => metric.avgHit.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.avgHit, 1),
			},
			{
				name: 'DPET',
				tooltip: 'Damage / Avg Cast Time',
				getValue: (metric: ActionMetrics) => metric.dpet,
				//getDisplayString: (metric: ActionMetrics) => metric.dpet.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.dpet, 1),
			},
			{
				name: 'DPR',
				tooltip: 'Damage / Avg Resource Cost',
				getValue: (metric: ActionMetrics) => metric.dpr,
				//getDisplayString: (metric: ActionMetrics) => metric.dpr.toFixed(1)
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.dpr, 1),
			},
			{
				name: 'TPS',
				tooltip: 'Threat / Encounter Duration',
				columnClass: 'threat-metrics',
				getValue: (metric: ActionMetrics) => metric.tps,
				//getDisplayString: (metric: ActionMetrics) => metric.tps.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.tps, 1),
			},
			{
				name: 'Avg Cast',
				tooltip: 'Threat / Casts',
				columnClass: 'threat-metrics',
				getValue: (metric: ActionMetrics) => metric.avgCastThreat,
				//getDisplayString: (metric: ActionMetrics) => metric.avgCastThreat.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.avgCastThreat, 1),
			},
			{
				name: 'Avg Hit',
				tooltip: 'Threat / (Hits + Crits + Glances + Blocks)',
				columnClass: 'threat-metrics',
				getValue: (metric: ActionMetrics) => metric.avgHitThreat,
				//getDisplayString: (metric: ActionMetrics) => metric.avgHitThreat.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.avgHitThreat, 1),
			},
			{
				name: 'Casts',
				tooltip: 'Casts',
				getValue: (metric: ActionMetrics) => metric.casts,
				//getDisplayString: (metric: ActionMetrics) => metric.casts.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.casts, 1),
			},
			{
				name: 'Hits',
				tooltip: 'Hits + Crits + Glances + Blocks',
				getValue: (metric: ActionMetrics) => metric.landedHits,
				//getDisplayString: (metric: ActionMetrics) => metric.landedHits.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.landedHits, 1),
			},
			{
				name: 'Miss %',
				tooltip: 'Misses / Swings',
				getValue: (metric: ActionMetrics) => metric.missPercent,
				//getDisplayString: (metric: ActionMetrics) => metric.missPercent.toFixed(2) + '%',
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.missPercent, 1),
			},
			{
				name: 'Dodge %',
				tooltip: 'Dodges / Swings',
				getValue: (metric: ActionMetrics) => metric.dodgePercent,
				//getDisplayString: (metric: ActionMetrics) => metric.dodgePercent.toFixed(2) + '%',
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.dodgePercent, 1),
			},
			{
				name: 'Parry %',
				tooltip: 'Parries / Swings',
				columnClass: 'in-front-of-target',
				getValue: (metric: ActionMetrics) => metric.parryPercent,
				//getDisplayString: (metric: ActionMetrics) => metric.parryPercent.toFixed(2) + '%',
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.parryPercent, 1),
			},
			{
				name: 'Block %',
				tooltip: 'Blocks / Swings',
				columnClass: 'in-front-of-target',
				getValue: (metric: ActionMetrics) => metric.blockPercent,
				//getDisplayString: (metric: ActionMetrics) => metric.blockPercent.toFixed(2) + '%',
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.blockPercent, 1),
			},
			{
				name: 'Glance %',
				tooltip: 'Glances / Swings',
				getValue: (metric: ActionMetrics) => metric.glancePercent,
				//getDisplayString: (metric: ActionMetrics) => metric.glancePercent.toFixed(2) + '%',
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.glancePercent, 1),
			},
			{
				name: 'Crit %',
				tooltip: 'Crits / Swings',
				getValue: (metric: ActionMetrics) => metric.critPercent,
				//getDisplayString: (metric: ActionMetrics) => metric.critPercent.toFixed(2) + '%',
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.critPercent, 1),
			},
		]);
	}

	getGroupedMetrics(resultData: SimResultData): Array<Array<ActionMetrics>> {
		const players = resultData.result.getPlayers(resultData.filter);
		if (players.length != 1) {
			return [];
		}
		const player = players[0];

		if (player.inFrontOfTarget) {
			this.rootElem.classList.remove('hide-in-front-of-target');
		} else {
			this.rootElem.classList.add('hide-in-front-of-target');
		}

		const actions = player.getMeleeActions().map(action => action.forTarget(resultData.filter));
		const actionGroups = ActionMetrics.groupById(actions);

		const petsByName = bucket(player.pets, pet => pet.name);
		const petGroups = Object.values(petsByName).map(pets => ActionMetrics.joinById(pets.map(pet => pet.getMeleeActions().map(action => action.forTarget(resultData.filter))).flat(), true));

		return actionGroups.concat(petGroups);
	}

	mergeMetrics(metrics: Array<ActionMetrics>): ActionMetrics {
		return ActionMetrics.merge(metrics, true, metrics[0].unit?.petActionId || undefined);
	}

	shouldCollapse(metric: ActionMetrics): boolean {
		return !metric.unit?.isPet;
	}
}
